# Credly Badging Integration
import requests

CREDLY_API_KEY = "1Y05NShfRax0xuUPATvRNJOEEl4XcQgze"
CREDLY_ORG_ID = "your_org_id"

def issue_badge(user_email, badge_template_id):
    """Issue a digital badge"""
    response = requests.post(
        f"https://api.credly.com/v1/organizations/{CREDLY_ORG_ID}/badges",
        headers={
            "Authorization": f"Bearer {CREDLY_API_KEY}",
            "Content-Type": "application/json"
        },
        json={
            "recipient_email": user_email,
            "badge_template_id": badge_template_id,
            "issued_to_organization": False
        }
    )
    return response.json()
